 $('zc').addEventListener('click',e=>{const b=e.target.closest('[data-m]');if(!b)return;const c=new Set(parseM($('z3').value)),k=+b.dataset.m;c.has(k)?c.delete(k):c.add(k);$('z3').value=[...c].sort((a,b)=>a-b).join(', ')});
